  begin
    if ((imd_val_q_iC[0][31]^op_denominator_qC[31])==1'b0)
      begin
        is_greater_equalC =  (res_adder_hC[31]==1'b0) ;
      end
    else
      begin
        is_greater_equalC = imd_val_q_iC[0][31];
      end
  end
assign div_sign_aA = op_a_iA[31]&signed_mode_iA[0];
assign div_sign_aB = op_a_iB[31]&signed_mode_iB[0];
assign div_sign_aC = op_a_iC[31]&signed_mode_iC[0];
assign div_sign_bA = op_b_iA[31]&signed_mode_iA[1];
assign div_sign_bB = op_b_iB[31]&signed_mode_iB[1];
assign div_sign_bC = op_b_iC[31]&signed_mode_iC[1];
assign div_change_signA =  (div_sign_aA^div_sign_bA) &~div_by_zero_qVotedA;
assign div_change_signB =  (div_sign_aB^div_sign_bB) &~div_by_zero_qVotedB;
assign div_change_signC =  (div_sign_aC^div_sign_bC) &~div_by_zero_qVotedC;
assign rem_change_signA = div_sign_aA;
assign rem_change_signB = div_sign_aB;
assign rem_change_signC = div_sign_aC;

always_comb
  begin
    div_counter_dA = div_counter_qVotedA - 5'h1;
    op_remainder_dA = imd_val_q_iA[0];
    op_quotient_dA = op_quotient_qVotedA;
    md_state_dA = md_state_qVotedA;
    op_numerator_dA = op_numerator_qVotedA;
    op_denominator_dA = op_denominator_qA;
    alu_operand_a_oA = {32'h0, 1'b1};
    alu_operand_b_oA = {~op_b_iA, 1'b1};
    div_validA = 1'b0;
    div_holdA = 1'b0;
    div_by_zero_dA = div_by_zero_qVotedA;
    unique case (md_state_qVotedA)
      MD_IDLE : 
        begin
          if (operator_iA==MD_OP_DIV)
            begin
              op_remainder_dA = '1;
              md_state_dA = equal_to_zero_iA ? MD_FINISH : MD_ABS_A;
              div_by_zero_dA = equal_to_zero_iA;
            end
          else
            begin
              op_remainder_dA = {2'b0, op_a_iA};
              md_state_dA = equal_to_zero_iA ? MD_FINISH : MD_ABS_A;
            end
          alu_operand_a_oA = {32'h0, 1'b1};
          alu_operand_b_oA = {~op_b_iA, 1'b1};
          div_counter_dA = 5'd31;
        end
      MD_ABS_A : 
        begin
          op_quotient_dA = '0;
          op_numerator_dA = div_sign_aA ? alu_adder_iA : op_a_iA;
          md_state_dA = MD_ABS_B;
          div_counter_dA = 5'd31;
          alu_operand_a_oA = {32'h0, 1'b1};
          alu_operand_b_oA = {~op_a_iA, 1'b1};
        end
      MD_ABS_B : 
        begin
          op_remainder_dA = {33'h0, op_numerator_qVotedA[31]};
          op_denominator_dA = div_sign_bA ? alu_adder_iA : op_b_iA;
          md_state_dA = MD_COMP;
          div_counter_dA = 5'd31;
          alu_operand_a_oA = {32'h0, 1'b1};
          alu_operand_b_oA = {~op_b_iA, 1'b1};
        end
      MD_COMP : 
        begin
          op_remainder_dA = {1'b0, next_remainderA[31:0], op_numerator_qVotedA[div_counter_dA]};
          op_quotient_dA = next_quotientA[31:0];
          md_state_dA = (div_counter_qVotedA==5'd1) ? MD_LAST : MD_COMP;
          alu_operand_a_oA = {imd_val_q_iA[0][31:0], 1'b1};
          alu_operand_b_oA = {~op_denominator_qA[31:0], 1'b1};
        end
      MD_LAST : 
        begin
          if (operator_iA==MD_OP_DIV)
            begin
              op_remainder_dA = {1'b0, next_quotientA};
            end
          else
            begin
              op_remainder_dA = {2'b0, next_remainderA[31:0]};
            end
          alu_operand_a_oA = {imd_val_q_iA[0][31:0], 1'b1};
          alu_operand_b_oA = {~op_denominator_qA[31:0], 1'b1};
          md_state_dA = MD_CHANGE_SIGN;
        end
      MD_CHANGE_SIGN : 
        begin
          md_state_dA = MD_FINISH;
          if (operator_iA==MD_OP_DIV)
            begin
              op_remainder_dA = (div_change_signA) ? {2'h0, alu_adder_iA} : imd_val_q_iA[0];
            end
          else
            begin
              op_remainder_dA = (rem_change_signA) ? {2'h0, alu_adder_iA} : imd_val_q_iA[0];
            end
          alu_operand_a_oA = {32'h0, 1'b1};
          alu_operand_b_oA = {~imd_val_q_iA[0][31:0], 1'b1};
        end
      MD_FINISH : 
        begin
          md_state_dA = MD_IDLE;
          div_holdA = 1'b0;
          div_validA = 1'b1;
        end
      default : 
        begin
          md_state_dA = MD_IDLE;
        end
    endcase
  end

