        begin
          op_remainder_dB = {1'b0, next_remainderB[31:0], op_numerator_qVotedB[div_counter_dB]};
          op_quotient_dB = next_quotientB[31:0];
          md_state_dB = (div_counter_qVotedB==5'd1) ? MD_LAST : MD_COMP;
          alu_operand_a_oB = {imd_val_q_iB[0][31:0], 1'b1};
          alu_operand_b_oB = {~op_denominator_qB[31:0], 1'b1};
        end
      MD_LAST : 
        begin
          if (operator_iB==MD_OP_DIV)
            begin
              op_remainder_dB = {1'b0, next_quotientB};
            end
          else
            begin
              op_remainder_dB = {2'b0, next_remainderB[31:0]};
            end
          alu_operand_a_oB = {imd_val_q_iB[0][31:0], 1'b1};
          alu_operand_b_oB = {~op_denominator_qB[31:0], 1'b1};
          md_state_dB = MD_CHANGE_SIGN;
        end
      MD_CHANGE_SIGN : 
        begin
          md_state_dB = MD_FINISH;
          if (operator_iB==MD_OP_DIV)
            begin
              op_remainder_dB = (div_change_signB) ? {2'h0, alu_adder_iB} : imd_val_q_iB[0];
            end
          else
            begin
              op_remainder_dB = (rem_change_signB) ? {2'h0, alu_adder_iB} : imd_val_q_iB[0];
            end
          alu_operand_a_oB = {32'h0, 1'b1};
          alu_operand_b_oB = {~imd_val_q_iB[0][31:0], 1'b1};
        end
      MD_FINISH : 
        begin
          md_state_dB = MD_IDLE;
          div_holdB = 1'b0;
          div_validB = 1'b1;
        end
      default : 
        begin
          md_state_dB = MD_IDLE;
        end
    endcase
  end

